#include <iostream>
struct Base {
    void f() { std::cout << "B1 "; }
    virtual void g() { std::cout << "B2"; }
};
struct Derived : Base {
    void f() { std::cout << "D1 "; }
    void g() override { std::cout << "D2"; }
};
int main() {
    Derived d;
    Base& b = d;
    b.f(); b.g();
}

