#include <iostream>
struct Base {
    virtual int calc(int x = 10) { return x; }
};
struct Sub : Base {
    int calc(int x = 99) override { return x * 2; }
};
int main() {
    Sub s;
    Base* p = &s;
    std::cout << p->calc();
}

